INSERT INTO `funds` (`id`, `name`, `class`, `fund_code`, `class_code`, `user_id`, `created_at`, `updated_at`, `template`, `fund_date`, `description`, `logo_url`, `category`, `domicile`, `minimums`, `subsequent_subscription_amount`, `benchmark`, `unit_price`, `isin_number`, `apir_arsn`, `sedol`, `risk_of_loss`, `risk_indicator`, `risk_indicator_definition`, `time_horizon`, `base_currency`, `fund_managers`, `foreign_assets`, `inception_date`, `number_of_units`, `portfolio_size`, `equity_indicator_description`, `last_distributions`, `management_company`, `responsible_entity`, `custodian`, `distribution_partner`, `fund_features`, `shariah_supervisory_board`, `depository`, `investment_manager`, `sub_investment_manager`, `type_of_shares`, `fees_summary`, `master_fund`, `master_fund_returns`, `lipper_award`, `page2_content`, `income_distributions`, `portfolio_orientation`, `income_characteristics`, `significant_restrictions`, `footer_info`, `footer_email`, `footer_phone`, `footer_website`, `footer_logo_url`, `footer_free_of_charge`, `important_info_title`, `important_info_published_date`, `important_info_paragraphs`, `asset_allocation`, `top_investments`, `performance_table`, `chart_data`, `sector_allocation`, `chart_description`, `fees`) VALUES (49,'FOORD SHARIAH INCOME FUND — CLASS B',NULL,'841','B',1,'2026-08-31 12:45:41','2026-09-08 07:08:29','show-shariah-income','31 August 2026','The fund aims to provide an income yield exceeding returns from money market portfolios with a low probability of capital loss over an investment horizon of six months to one year. The fund is suitable for South African Islamic investors seeking an attractive income yield and who have a very low tolerance for short-term capital loss or price volatility.','https://foord.co.za/themes/custom/mirum/logo.png','South African — Multi Asset — Income','South Africa','By agreement',NULL,'Alexander Forbes Short-term Fixed-interest Composite Index (Stefi)','1017.19 cents','ZAE000338331',NULL,NULL,'Low in periods longer than one year, moderate in periods shorter than six months.',NULL,NULL,'One to two years.','South African rands','Farzana Bayat and Rashaad Tayob','Direct investment in global hard-currency securities, with active currency management.','6 May 2025','3.2 million','R32.2 million',NULL,'30/06/2026: 18.78 cents<br>31/03/2026: 17.89 cents','Foord Unit Trusts (RF) (Pty) Ltd<br>VAT Registration Number: 4560201594',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{\"shariahFunds\": {\"title\": \"FOORD SHARIAH FUNDS\", \"paragraphs\": [\"Foord Shariah compliant funds are managed according to the rulings and guidelines issued by the Shariah Advisory Committee (SAC). The term Shariah refers to Islamic Law as interpreted by the Shariah Advisory Committee appointed by Foord. The SAC is an independent body of scholars, specialist in Islamic commercial law and are entrusted with the duty of directing, reviewing, and supervising the activities of the Foord Shariah compliant funds to ensure that these funds are always Shariah compliant.\", \"Non-permissible income (NPI) refers to non-Shariah compliant income, primarily being interest or resulting from involvement in prohibited activities. Such NPI may inadvertently be earned by the Foord Shariah compliant fund portfolios. Any  income earned in the Foord Shariah compliant funds deemed non-permissible by the SAC will be paid to the charitable organisations approved by the SAC in accordance with the principles of Shariah. Such NPI does not form part of the investor\'s income nor will such NPI be re-invested within the Foord Shariah compliant funds.\"]}}','End-March, end-June, end-September and end-December each year.','A dynamic mix of Islamic deposits and sukuks and listed property counters, with some select foreign securities and active currency management. Weighted average duration is typically less than three years.','High income yield, expected to exceed average money market yields.','Maximum equity exposure of 10%; maximum property exposure of 25%; maximum offshore exposure of 45%; complies with pension fund investment regulations (Regulation 28). Shariah compliant, determined by the Shariah Advisory Committee.','Please visit our website for more information regarding our investment track record, the Foord team, current and archived news items, or forms and documents.','unittrusts@foord.co.za','+27 21 532 6969','www.foord.co.za',NULL,'This information is provided free of charge.','IMPORTANT INFORMATION FOR INVESTORS','Published on 09 September 2026.','[\"Foord Unit Trusts (RF) (Pty) Ltd (Foord) is an approved CISCA Management Company (#10), regulated by the Financial Sector Conduct Authority. Portfolios are managed by Foord Asset Management (Pty) Ltd, an authorised Financial Services Provider (FSP: 578). The custodian/trustee of Foord Unit Trusts is RMB Custody and Trustee Services (a division of FirstRand Bank Limited), contactable on T: 087 736 1732,F: 0860 557 774, www.rmb.co.za.\", \"Collective Investment Schemes in Securities (unit trusts) are generally medium- to long-term investments. The value of participatory interests (units) may go down as well as up and past performance is not necessarily a guide to the future. Performance is calculated for the portfolio. Individual investor performance may differ as a result of the actual investment date, the date of reinvestment and withholding taxes. Performance may be affected by changes in the market or economic conditions and legal, regulatory and tax requirements. Foord does not provide any guarantee either with respect to the capital or the performance return of the investment. Unit trusts are traded at ruling prices and can engage in borrowing. Foord does not engage in scrip lending. Commission and incentives may be paid and if so, this cost is not borne by the investor. A schedule of fees and charges and maximum commissions is available on request. Distributions may be subject to mandatory withholding taxes. Portfolio information is presented using effective exposures. A fund of funds invests only in other Collective Investment Scheme portfolios, which may levy their own charges, which could result in a higher fee structure. A feeder fund is a portfolio that, apart from assets in liquid form, consists solely of units in a single portfolio of a Collective Investment Scheme which could result in a higher fee structure. Foord is authorised to close the portfolio to new investors in order to manage the portfolio more efficiently in accordance with its mandate.\", \"Unit trust prices are calculated on a net asset value basis, which is the total value of all assets in the portfolio including any income accruals and less any permissible deductions from the portfolio. Forward pricing is used. Prices are determined at 15h00 each business day and are published daily on www.foord.co.za. The cut-off time for instruction is 14h00 each business day.\", \"The portfolio may include underlying foreign investments. Fluctuations or movements in exchange rates may cause the value of underlying foreign investments to go up or down. The underlying foreign investments may be adversely affected by political instability as well as exchange controls, changes in taxation, foreign investment policies, restrictions on repatriation of investments and other restrictions and controls that may be imposed by the relevant authorities in the relevant countries.\", \"This document is not an advertisement, but is provided exclusively for information purposes and is not an offer or solicitation to purchase, sell or otherwise deal with any particular investment. Economic forecasts and predictions are based on Foord’s interpretation of current factual information and exploration of economic activity based on expectation for future growth under normal economic conditions, not dissimilar to previous cycles. Forecasts and commentaries are provided for information purposes only and are not guaranteed to occur. While we have taken and will continue to take care that the information contained herein is true and correct, we request that you report any errors to Foord at unittrusts@foord.co.za. The document is protected by copyright and may not be altered without prior written consent.\", \"Foord Asset Management is a member of the Association for Savings and Investment SA.\", \"This is a Minimum Disclosure Document.\"]','{\"rows\": [{\"sa\": \"8.3\", \"name\": \"Cash and call\", \"total\": \"8.5\", \"change\": \"▼ 0.2\", \"foreign\": \"0.1\", \"changeDirection\": \"down\"}, {\"sa\": \"0.0\", \"name\": \"Equities\", \"total\": \"1.9\", \"change\": \"▼ 0.0\", \"foreign\": \"1.9\", \"changeDirection\": \"down\"}, {\"sa\": \"65.0\", \"name\": \"Income\", \"total\": \"65.0\", \"change\": \"▲ 0.1\", \"foreign\": \"0.0\", \"changeDirection\": \"up\"}, {\"sa\": \"24.1\", \"name\": \"Sukuks\", \"total\": \"24.1\", \"change\": \"▲ 0.2\", \"foreign\": \"0.0\", \"changeDirection\": \"up\"}, {\"sa\": \"0.5\", \"name\": \"Property\", \"total\": \"0.5\", \"change\": \"▲ 0.0\", \"foreign\": \"0.0\", \"changeDirection\": \"up\"}], \"title\": \"PORTFOLIO STRUCTURE %\", \"total\": {\"sa\": \"98.0\", \"name\": \"TOTAL\", \"total\": \"100.0\", \"change\": \"\", \"foreign\": \"2.0\"}, \"headers\": [\"\", \"SA\", \"FOREIGN\", \"TOTAL\", \"CHANGE\"], \"subtitle\": \"Change since 30 June 2026\", \"creditExposure\": {\"title\": \"CREDIT EXPOSURE BREAKDOWN %\", \"ratings\": [{\"name\": \"F1+\", \"value\": \"73\"}, {\"name\": \"F1\", \"value\": \"-\"}, {\"name\": \"AAA\", \"value\": \"24\"}, {\"name\": \"AA\", \"value\": \"-\"}, {\"name\": \"A\", \"value\": \"-\"}, {\"name\": \"Other\", \"value\": \"2\"}], \"sectors\": [{\"name\": \"Big four banks\", \"value\": \"73\"}, {\"name\": \"SA Corporates\", \"value\": \"-\"}, {\"name\": \"SA Government\", \"value\": \"24\"}, {\"name\": \"US Government\", \"value\": \"-\"}, {\"name\": \"Other\", \"value\": \"2\"}]}, \"portfolioStatistics\": {\"rows\": [{\"sup\": \"1\", \"name\": \"Yield\", \"value\": \"8.60%\"}, {\"name\": \"Spread to JIBAR\", \"value\": \"1.79%\"}, {\"spacer\": true}, {\"sup\": \"2\", \"bold\": true, \"name\": \"SA duration\", \"value\": \"5.01\"}, {\"name\": \"— SA fixed rate duration\", \"value\": \"5.01\"}, {\"name\": \"— SA floating rate duration\", \"value\": \"-\"}, {\"name\": \"— SA inflation linked duration\", \"value\": \"-\"}, {\"sup\": \"2\", \"bold\": true, \"name\": \"Offshore duration\", \"value\": \"-\"}, {\"name\": \"— Offshore fixed rate duration\", \"value\": \"-\"}, {\"name\": \"— Offshore inflation linked\", \"value\": \"-\"}], \"title\": \"PORTFOLIO STATISTICS\"}}',NULL,'{\"rows\": [{\"1yr\": 8, \"ytd\": 5, \"name\": \"Fund\", \"3months\": 1.9, \"6months\": 3.8, \"cashValue\": \"R 110,657\", \"distYield\": 5, \"thisMonth\": 0.6, \"sinceInception\": 8}, {\"1yr\": 7, \"ytd\": 4.5, \"name\": \"Benchmark\", \"3months\": 1.7, \"6months\": 3.4, \"cashValue\": \"R 109,537\", \"distYield\": 4.5, \"thisMonth\": 0.6, \"sinceInception\": 7.1}], \"title\": \"PORTFOLIO PERFORMANCE % (PERIODS GREATER THAN ONE YEAR ARE ANNUALISED⁵)\", \"headers\": [\"\", \"CASH<br>VALUE⁴\", \"SINCE<br>INCEPTION\", \"1<br>YEAR\", \"6<br>MONTHS\", \"3<br>MONTHS\", \"<br>YTD\", \"THIS<br>MONTH\"], \"footnotes\": [\"¹ The yield for an income-generating investment is its annual income distribution divided by its current price, expressed as a percentage. For the Fund, the yield represents the weighted average yield of the underlying income-generating investments as at the last day of the month. The yield  is subject to change as market conditions and the composition of the underlying investments change.\", \"² Duration measures the sensitivity of the price of an income-generating instrument to changes in prevailing market profit rates or yields. A lower duration indicates lower sensitivity to changes in market conditions, while a higher duration indicates greater sensitivity.\", \"³ Average credit rating from rating agencies.\", \"⁴ Current value of R100 000 notional lump sum invested at inception, distributions reinvested (graphically represented in R’000s above)\", \"⁵ Converted to reflect the average yearly return for each period presented.\", \"⁶ Net of fees and expenses.\", \"Note: Totals may not cast perfectly due to rounding.\"]}','{\"headers\": [\"Start Date\", \"Description\", \"841 B Class [iB]\", \"841 Fund Benchmark [STFIND]\", \"ECPI\", null], \"rightTitle\": \"PERFORMANCE VS BENCHMARK\", \"portfolioData\": [{\"date\": \"2025-05\", \"fund\": 100.52, \"benchmark\": 100.51, \"inflation\": 100.16}, {\"date\": \"2025-06\", \"fund\": 101.18, \"benchmark\": 101.14, \"inflation\": 100.46}, {\"date\": \"2025-07\", \"fund\": 101.79, \"benchmark\": 101.76, \"inflation\": 101.34}, {\"date\": \"2025-08\", \"fund\": 102.49, \"benchmark\": 102.34, \"inflation\": 101.24}, {\"date\": \"2025-09\", \"fund\": 103.1, \"benchmark\": 102.97, \"inflation\": 101.44}, {\"date\": \"2025-10\", \"fund\": 104.04, \"benchmark\": 103.58, \"inflation\": 101.54}, {\"date\": \"2025-11\", \"fund\": 104.69, \"benchmark\": 104.13, \"inflation\": 101.44}, {\"date\": \"2025-12\", \"fund\": 105.38, \"benchmark\": 104.78, \"inflation\": 101.64}, {\"date\": \"2026-01\", \"fund\": 105.96, \"benchmark\": 105.36, \"inflation\": 101.83}, {\"date\": \"2026-02\", \"fund\": 106.65, \"benchmark\": 105.9, \"inflation\": 102.22}, {\"date\": \"2026-03\", \"fund\": 107.26, \"benchmark\": 106.52, \"inflation\": 102.81}, {\"date\": \"2026-04\", \"fund\": 108.06, \"benchmark\": 107.09, \"inflation\": 103.99}, {\"date\": \"2026-05\", \"fund\": 108.59, \"benchmark\": 107.66, \"inflation\": 104.68}, {\"date\": \"2026-06\", \"fund\": 109.26, \"benchmark\": 108.29, \"inflation\": 105.46}, {\"date\": \"2026-07\", \"fund\": 110.01, \"benchmark\": 108.91, \"inflation\": 105.66}, {\"date\": \"2026-08\", \"fund\": 110.66, \"benchmark\": 109.54, \"inflation\": 105.95}], \"maturitySpread\": {\"title\": \"MATURITY SPREAD %\", \"categories\": [{\"name\": \"0—1 years\", \"label\": \"31\", \"value\": 31}, {\"name\": \"1—3 years\", \"label\": \"-\", \"value\": 0}, {\"name\": \"3—7 years\", \"label\": \"43\", \"value\": 43}, {\"name\": \"7—12 years\", \"label\": \"24\", \"value\": 24}, {\"name\": \"> 12 years\", \"label\": \"-\", \"value\": 0}, {\"name\": \"Perpetual\", \"label\": \"2\", \"value\": 2}]}, \"portfolioLabels\": [\"Fund\", \"Benchmark\"]}',NULL,NULL,'{\"feeRates\": {\"rates\": [{\"name\": \"Initial, exit and switching fees\", \"value\": \"0.0%\"}, {\"name\": \"Manager’s charge\", \"value\": \"Zero fee class. Fee rates are by agreement only\"}], \"title\": \"FEE RATES\"}, \"totalInvestmentCharge\": {\"rows\": [{\"12m\": 0.58, \"36m\": 0.56, \"name\": \"Total expense ratio (TER)\"}, {\"12m\": 0, \"36m\": 0, \"name\": \"— Manager’s charge (basic)\"}, {\"12m\": 0.58, \"36m\": 0.56, \"name\": \"— VAT and sundry costs\"}, {\"12m\": 0, \"36m\": 0.01, \"name\": \"Transaction costs (incl VAT)\"}], \"title\": \"TOTAL INVESTMENT CHARGE %\", \"total\": {\"12m\": 0.58, \"36m\": 0.57, \"name\": \"Total investment charge\"}, \"headers\": [\"\", \"12 MONTHS\", \"36 MONTHS*\"], \"footnote\": \"*Estimated as the fund was incepted less than three  years ago. The manager has applied the best estimate of the costs annualised for a year which is grounded on fair principles of ASISA’s standard on the Calculation and Disclosure of Total Expense Ratios and Transaction costs.\", \"description\": \"A TER is a measure of a portfolio’s annual expenses, fees and charges, expressed as a percentage of the average daily value of the portfolio. These expenses include the annual fee, VAT, audit fees, bank charges and costs (excluding trading costs) incurred in any underlying funds. Included in the TER, but separately disclosed, is a performance fee (or credit) resulting from overperformance (or underperformance) against the benchmark. A higher TER does not necessarily imply a poor return, nor does a low TER imply a good return. The current TER cannot be regarded as an indication of future TERs. Performance return information and prices are always stated net of the expenses, fees and charges included in the TER.\"}}');
INSERT INTO `funds` (`id`, `name`, `class`, `fund_code`, `class_code`, `user_id`, `created_at`, `updated_at`, `template`, `fund_date`, `description`, `logo_url`, `category`, `domicile`, `minimums`, `subsequent_subscription_amount`, `benchmark`, `unit_price`, `isin_number`, `apir_arsn`, `sedol`, `risk_of_loss`, `risk_indicator`, `risk_indicator_definition`, `time_horizon`, `base_currency`, `fund_managers`, `foreign_assets`, `inception_date`, `number_of_units`, `portfolio_size`, `equity_indicator_description`, `last_distributions`, `management_company`, `responsible_entity`, `custodian`, `distribution_partner`, `fund_features`, `shariah_supervisory_board`, `depository`, `investment_manager`, `sub_investment_manager`, `type_of_shares`, `fees_summary`, `master_fund`, `master_fund_returns`, `lipper_award`, `page2_content`, `income_distributions`, `portfolio_orientation`, `income_characteristics`, `significant_restrictions`, `footer_info`, `footer_email`, `footer_phone`, `footer_website`, `footer_logo_url`, `footer_free_of_charge`, `important_info_title`, `important_info_published_date`, `important_info_paragraphs`, `asset_allocation`, `top_investments`, `performance_table`, `chart_data`, `sector_allocation`, `chart_description`, `fees`) VALUES (50,'FOORD GLOBAL EQUITY AUSTRALIAN FEEDER FUND — CLASS A','A','880','A',1,'2026-08-31 13:59:16','2026-08-31 15:33:44','show-australian-feeder','31 July 2026','The master fund aims to achieve long-term capital growth from an actively managed and diversified portfolio of global developed and emerging market equities and to thereby outperform its MSCI All Country world equity benchmark, without assuming greater risk. The fund is appropriate for investors with a long investment horizon and who can withstand bouts of investment volatility in the short to medium term.','https://foord.co.za/themes/custom/mirum/logo.png','Australia Fund Equity World Large Blend','Australia','US$1 000 000 or equivalent','US$100 000','MSCI All Country World Net Total Return Index (AUD)','A$22.35','AU60ETL37743','ETL3774AU<br>659 724 286',NULL,NULL,NULL,NULL,'Longer than five years.','Australian dollar (A$)<br>Master fund: US dollar','Brian Arcese, Ishreth Hassen and Jing Cong Xue',NULL,'11 August 2022','519 004','A$11.6 million<br>Master fund: $851.1 million',NULL,NULL,NULL,'Equity Trustees Limited','Mainstream Fund Services Pty Ltd','Shed Enterprises Pty Limited','Multiple-counsellor approach<br>Risk aware and active<br>Long only, high conviction<br>Benchmark agnostic',NULL,NULL,'Foord Asset Management (Singapore) Pte. Limited',NULL,'Accumulation','Management fees: 1.00% is levied in the Master Fund<br>Indirect costs: 0.20%',NULL,NULL,NULL,'{\"sharePricing\": {\"text\": \"Application or Withdrawal price is determined in accordance with the Fund’s Constitution on a Business Day. In general terms, the price is equal to the Net Asset Value (“NAV”) of the Fund, divided by the number of units in issue and adjusted for current transaction costs of 0.15% which is also know as the buy/sell spread.\", \"title\": \"UNIT PRICING AND TRANSACTIONS\"}, \"moreAboutFund\": {\"title\": \"MORE ABOUT THE FUND\", \"paragraphs\": [\"The responsible entity, Equity Trustees Limited (“Equity Trustees”) (ABN 46 004 031 298/ AFSL 240975), is a subsidiary of EQT Holdings Limited (ABN 22 607 797 615) listed on the Australian Securities Exchange (ASX: EQT). Neither Equity Trustee or any of its related parties, their employees or directors, provide any warranty of accuracy or reliability in relation to such information or accepts any liability to any person who relies on it.\", \"The fund invests exclusively in Class B shares of Foord SICAV - Foord Global Equity Fund (Luxembourg) (the \\\"Master Fund\\\"). The Master Fund is actively managed and not constrained by the benchmark in its portfolio positioning. The Manager decides on the portfolio\'s asset selection, regional allocation, sector views and overall level of exposure to the market to take advantage of investment opportunities. The Master Fund can borrow up to 10% of NAV and does not engage in scrip lending. Since inception, no dividends or distributions were declared.\", \"This document is prepared by the investment manager which is licensed as a foreign Australian Financial Services Licensee (AFSL 542514) to provide financial services to wholesale clients in Australia.\"]}}',NULL,NULL,NULL,NULL,'Please visit our website for more information regarding our investment track record, our Foord team, current and archived news items, or forms and documents.','investments@foord.com','+65 6521 1100 | +27 21 532 6969','www.foord.com',NULL,'This information is provided free of charge.','IMPORTANT INFORMATION FOR INVESTORS','Published on 14 August 2026.','[\"This is a marketing communication. Investors should read the Product Disclosure Statement (\\\"PDS\\\") — available in English at www.foord.com — and seek professional advice or consider investment suitability before investing in the fund. This document is not an advertisement but is provided for information purposes and should not be regarded as an offer or solicitation to purchase, sell or otherwise deal in the fund.\", \"Foord does not guarantee the capital invested or the performance of the investment. The portfolio includes qualifying investments listed on regulated exchanges outside the fund\'s domicile that carry risks as described in the prospectus, including the possibility of non-recoverable withholding taxes and non-repatriation of funds. Investment values and some costs may fluctuate because of factors including but not limited to currency exchange rates that can be affected by a wide range of economic factors.\", \"Economic forecasts and predictions are based on Foord’s interpretation of current factual information, and exploration of economic activity based on expectation for future growth under normal economic conditions, not dissimilar to previous cycles. Forecasts and commentaries are provided for information purposes only and are not guaranteed to occur.\", \"While we have taken and will continue to take care that the information contained herein is true and correct, neither Foord, Equity Trustees nor any of their related parties, employees or directors, provide any warranty of accuracy or reliability in relation to such information or accepts any liability to any person who relies on it.\", \"The document is protected by copyright and may not be altered without Foord’s consent.\"]','{\"geographicEquityExposure\": [{\"fund\": 31, \"name\": \"North America\", \"benchmark\": 65}, {\"fund\": 30, \"name\": \"EM Asia\", \"benchmark\": 9}, {\"fund\": 33, \"name\": \"Europe\", \"benchmark\": 15}, {\"fund\": 6, \"name\": \"Pacific\", \"benchmark\": 8}]}','{\"rows\": [{\"market\": \"HKG\", \"security\": \"Tencent Holdings\", \"assetClass\": \"Communication services\", \"percentage\": 6.7}, {\"market\": \"USA\", \"security\": \"Alphabet\", \"assetClass\": \"Communication services\", \"percentage\": 6.4}, {\"market\": \"TWN\", \"security\": \"TSMC\", \"assetClass\": \"Information technology\", \"percentage\": 6}, {\"market\": \"USA\", \"security\": \"JD.Com\", \"assetClass\": \"Consumer discretionary\", \"percentage\": 5.6}, {\"market\": \"HKG\", \"security\": \"Alibaba\", \"assetClass\": \"Consumer discretionary\", \"percentage\": 5.1}, {\"market\": \"CHE\", \"security\": \"Roche\", \"assetClass\": \"Healthcare\", \"percentage\": 4.6}, {\"market\": \"GBR\", \"security\": \"Fevertree Drinks\", \"assetClass\": \"Consumer staples\", \"percentage\": 4.1}, {\"market\": \"GBR\", \"security\": \"Wise PLC\", \"assetClass\": \"Financials\", \"percentage\": 3.3}, {\"market\": \"USA\", \"security\": \"Microsoft\", \"assetClass\": \"Information technology\", \"percentage\": 3}, {\"market\": \"USA\", \"security\": \"Spotify\", \"assetClass\": \"Communication services\", \"percentage\": 2.6}], \"title\": \"TOP 10 INVESTMENTS\", \"headers\": [\"SECURITY\", \"SECTOR\", \"MA