INSERT INTO `funds` (`id`, `name`, `class`, `fund_code`, `class_code`, `user_id`, `created_at`, `updated_at`, `template`, `fund_date`, `description`, `logo_url`, `category`, `domicile`, `minimums`, `subsequent_subscription_amount`, `benchmark`, `unit_price`, `isin_number`, `apir_arsn`, `sedol`, `risk_of_loss`, `risk_indicator`, `risk_indicator_definition`, `time_horizon`, `base_currency`, `fund_managers`, `foreign_assets`, `inception_date`, `number_of_units`, `portfolio_size`, `equity_indicator_description`, `last_distributions`, `management_company`, `responsible_entity`, `custodian`, `distribution_partner`, `fund_features`, `shariah_supervisory_board`, `depository`, `investment_manager`, `sub_investment_manager`, `type_of_shares`, `fees_summary`, `master_fund`, `master_fund_returns`, `lipper_award`, `page2_content`, `income_distributions`, `portfolio_orientation`, `income_characteristics`, `significant_restrictions`, `footer_info`, `footer_email`, `footer_phone`, `footer_website`, `footer_logo_url`, `footer_free_of_charge`, `important_info_title`, `important_info_published_date`, `important_info_paragraphs`, `asset_allocation`, `top_investments`, `performance_table`, `chart_data`, `sector_allocation`, `chart_description`, `fees`) VALUES (52,'FOORD ASIA EX-JAPAN FUND — CLASS R1','R1','879','R1',1,'2026-08-31 16:22:37','2026-08-31 19:29:30','show-asia-ex-japan','31 July 2026','The fund aims to achieve long-term capital growth from an actively managed and diversified portfolio of listed equities whose businesses are predominantly focused on the Asia ex-Japan region and to thereby outperform its MSCI Asia ex-Japan benchmark, without assuming greater risk. The fund is appropriate for investors with a long investment horizon and who can withstand bouts of investment volatility in the short to medium term.','https://foord.co.za/themes/custom/mirum/logo.png','Asia ex-Japan Equity','Luxembourg','US$10 000','US$1 000','MSCI All Country Asia ex-Japan net total return (USD) Index','$13.40','LU2107516705',NULL,NULL,NULL,NULL,NULL,'Longer than five years','US dollars','Ishreth Hassen and Jing Cong Xue',NULL,'27 July 2021','1.7 million','$192.8 million','Indicates the relative weight of equities in the portfolio. A higher weight could result in increased volatility of returns.',NULL,'FundSight S.A.',NULL,NULL,NULL,NULL,NULL,'CACEIS Bank, Luxembourg Branch','Foord Asset Management (Guernsey) Limited','Foord Asset Management (Singapore) Pte. Limited','Accumulation','Standard minimum annual fee: 0.50%<br>Performance fee sharing rate: 15%<br>Maximum annual fee: uncapped',NULL,NULL,NULL,'{\"sharePricing\": {\"text\": \"Shares will be issued or realised on a forward pricing basis only on Valuation Day (as defined in the prospectus) and calculated on the net asset value (“NAV) represented by one share. Prices are published on www.foord.com within two business days after the relevant Valuation Day. All dealing application requests must be received before 08h00 (Central European time) on each Valuation Day.\", \"title\": \"SHARE PRICING AND TRANSACTIONS\"}, \"moreAboutFund\": {\"title\": \"MORE ABOUT THE FUND\", \"paragraphs\": [\"The fund is authorised in Luxembourg and regulated by the Commission de Surveillance du Secteur Financier (CSSF). It is a medium-high-risk fund; rated 5 out of 7 using the Synthetic Risk and Reward Indictor (SRRI) calculation methodology guided by the European Commission. The fund is actively managed and not constrained by the benchmark in its portfolio positioning. The Manager decides on the portfolio\'s asset selection, regional allocation, sector views and overall level of exposure to the market to take advantage of investment opportunities. The fund can borrow up to 10% of NAV and does not engage in scrip lending. Since inception, no subscription fees or realisation fees were charged and no dividends or distributions were declared. Refer to the Key Information Document for more information.\", \"The Management Company may terminate the arrangements made for marketing of collective investment undertakings in accordance with Article 93a of Directive 2009/65/EC and Article 32a Directive 2011/611/EU. Please contact FundSight S.A. (formerly known as Lemanik Asset Management S.A.) on T: +352 26 39 60 or E: info@fundsight.com on regulatory matters. A summary of investor rights is available in English at www.foord.com.\"]}, \"performanceFees\": {\"title\": \"PERFORMANCE FEES\", \"paragraphs\": [\"Performance fees align investor and manager return objectives by rewarding the manager for outperformance. A performance fee is chargeable only when the portfolio performance exceeds the benchmark. Should the portfolio underperform it must first recover the underperformance since the performance fee last crystallised or the inception of the share class, whichever is later.\", \"The performance fee is calculated and accrued on a daily basis. If the performance conditions are no longer satisfied, all performance fees previously accrued during that accounting period (calendar year) are reversed.\", \"Included in the TER disclosure is performance fee for outperforming the benchmark. Subject to an overall minimum, the annual fee may be increased by the performance fee, calculated as the difference between the portfolio performance and the benchmark return for the same period, multiplied by the performance fee sharing rate.\"]}, \"performanceFeeExamples\": {\"rows\": [{\"name\": \"Share class performance\", \"values\": [\"4.00%\", \"4.00%\", \"5.00%\", \"-4.00%\"]}, {\"name\": \"Benchmark performance\", \"values\": [\"6.00%\", \"2.00%\", \"3.00%\", \"-5.00%\"]}, {\"name\": \"Sub-fund’s GAV<sup>1</sup>\", \"values\": [\"$1,040,000\", \"$1,081,600\", \"$1,050,000\", \"$960,000\"]}, {\"name\": \"Notional NAV<sup>1</sup>\", \"values\": [\"$1,060,000\", \"$1,081,200\", \"$1,030,000\", \"$950,000\"]}, {\"name\": \"Outperformance\", \"values\": [\"No\", \"$400\", \"$20,000\", \"$10,000\"]}, {\"name\": \"Is a performance fee payable\", \"values\": [\"No\", \"Yes\", \"Yes\", \"Yes\"]}, {\"name\": \"Performance fee accrual\", \"values\": [\"None\", \"$60<br>[$400 x 15%]\", \"$3,000<br>[$20,000 x 15%]\", \"$1,500<br>[$10,000 x 15%]\"]}], \"title\": \"PERFORMANCE FEE EXAMPLES FOR FOORD ASIA EX-JAPAN\", \"headers\": [\"\", \"PERIOD 1\", \"PERIOD 2\", \"PERIOD 3\", \"PERIOD 4\"], \"footnote\": \"<sup>1</sup> The notional GAVs illustrated in the above table are based on the initial value of USD1,000,000. The notional GAVs get reset after a performance fee is fully crystalised.\"}}',NULL,NULL,NULL,NULL,'Please visit our website for more information regarding our investment track record, the Foord team, current and archived news items, or forms and documents.','investments@foord.com','+65 6521 1100 | +27 21 532 6969','www.foord.com',NULL,'This information is provided free of charge.','IMPORTANT INFORMATION FOR INVESTORS','Published on 05 August 2026.','[\"This is a marketing communication. Investors should read the prospectus and key information documents (“PRIIP KID”) — available in English at www.foord.com — and seek professional advice or consider investment suitability before investing in the fund. This document is not an advertisement but is provided for information purposes and should not be regarded as an offer or solicitation to purchase, sell or otherwise deal in the fund.\", \"Foord does not guarantee the capital invested or the performance of the investment. The portfolio includes qualifying investments listed on regulated exchanges outside the fund\'s domicile that carry risks as described in the prospectus, including the possibility of non-recoverable withholding taxes and non-repatriation of funds. Investment values and some costs may fluctuate because of factors including but not limited to currency exchange rates that can be affected by a wide range of economic factors.\", \"Economic forecasts and predictions are based on Foord’s interpretation of current factual information, and exploration of economic activity based on expectation for future growth under normal economic conditions, not dissimilar to previous cycles. Forecasts and commentaries are provided for information purposes only and are not guaranteed to occur.\", \"While we have taken and will continue to take care that the information contained herein is true and correct, we do not guarantee the accuracy, timeliness or completeness of the information provided, and therefore disclaim any liability, damage (whether direct or consequential) or expense suffered as a result of reliance on the information.\", \"The document is protected by copyright and may not be altered without Foord’s consent.\", \"Note: For South African investors, this document is a Minimum Disclosure Document.\", \"A TER is a measure of a portfolio’s annual expenses, fees and charges, expressed as a percentage of the average value of the portfolio. A higher TER does not necessarily imply a poor return, nor does a low TER imply a good return. The current TER cannot be regarded as an indication of future TERs. The latest audited TER is 0.71%. The quantum of transaction costs is affected by the quantum of the gross in and outflows over the period presented. A schedule of fees and charges is disclosed in the prospectus or PRIIP KID, which are available on request.\"]','{\"geographicCountryExposure\": [{\"name\": \"China\", \"value\": 44.3}, {\"name\": \"United States of America\", \"value\": 14.4}, {\"name\": \"Taiwan, Province of China\", \"value\": 9.7}, {\"name\": \"Korea\", \"value\": 8.7}, {\"name\": \"Singapore\", \"value\": 5.4}, {\"name\": \"Hong Kong\", \"value\": 4.5}, {\"name\": \"Other\", \"value\": 13}]}','{\"rows\": [{\"market\": \"\", \"security\": \"TSMC\", \"assetClass\": \"\", \"percentage\": 8.4}, {\"market\": \"\", \"security\": \"APR Corp/Korea\", \"assetClass\": \"\", \"percentage\": 7.8}, {\"market\": \"\", \"security\": \"Tencent Holdings\", \"assetClass\": \"\", \"percentage\